@import 'lib/MOM/primary.cps';

glyph {
    base0: baseMaster0[Selector "glyph#" + this:id];
    base1: baseMaster1[Selector "glyph#" + this:id];
    base2: baseMaster2[Selector "glyph#" + this:id];
    base3: baseMaster3[Selector "glyph#" + this:id];
}


component {
    baseGlyphName: baseNode:baseGlyphName;
    /* FIXME: there's currently no way of interpolating transformation matrixes
see: https://github.com/graphicore/Atem-Property-Language/issues/1
    */
    transformation: baseNode:transformation;
    base0: parent:base0
        :children[index]
        ;
    base1: parent:base1
        :children[index]
        ;
    base2: parent:base2
        :children[index]
        ;
    base3: parent:base3
        :children[index]
        ;
}

contour > p {
    indexContour: parent:index;
    base0: parent:parent:base0
        :children[indexContour]
        :children[index]
        ;
    base1: parent:parent:base1
        :children[indexContour]
        :children[index]
        ;
    base2: parent:parent:base2
        :children[indexContour]
        :children[index]
        ;
    base3: parent:parent:base3
        :children[indexContour]
        :children[index]
        ;
}

center {
    indexPenstroke: parent:index;
    base0: parent:parent:base0
        :children[indexPenstroke]
        :children[index]
        ;
    base1: parent:parent:base1
        :children[indexPenstroke]
        :children[index]
        ;
    base2: parent:parent:base2
        :children[indexPenstroke]
        :children[index]
        ;
    base3: parent:parent:base3
        :children[indexPenstroke]
        :children[index]
        ;
}

center > * {
    indexPenstroke: parent:parent:index;
    indexCenter: parent:index;
    base0: parent:parent:parent:base0
        :children[indexPenstroke]
        :children[indexCenter]
        :children[index]
        ;
    base1: parent:parent:parent:base1
        :children[indexPenstroke]
        :children[indexCenter]
        :children[index]
        ;
    base2: parent:parent:parent:base2
        :children[indexPenstroke]
        :children[indexCenter]
        :children[index]
        ;
    base3: parent:parent:parent:base3
        :children[indexPenstroke]
        :children[indexCenter]
        :children[index]
        ;
}

* {
    /* Ensure that the used proportions sum up to 1.
     * Any other value produces usually unwanted effects.
     * If you don't want this in your master redefine it as
     * interpolationUnit: 1;
     */
    interpolationUnit: 1/(0
        + proportion0
        + proportion1
        + proportion2
        + proportion3);
    _p0: proportion0 * interpolationUnit;
    _p1: proportion1 * interpolationUnit;
    _p2: proportion2 * interpolationUnit;
    _p3: proportion3 * interpolationUnit;
}

glyph {
    width: 0
        + base0:width * _p0
        + base1:width * _p1
        + base2:width * _p2
        + base3:width * _p3;
    height: 0
        + base0:height * _p0
        + base1:height * _p1
        + base2:height * _p2
        + base3:height * _p3;
}

center, center > * {
    inLength: 0
        + base0:inLength * _p0
        + base1:inLength * _p1
        + base2:inLength * _p2
        + base3:inLength * _p3;
    outLength: 0
        + base0:outLength * _p0
        + base1:outLength * _p1
        + base2:outLength * _p2
        + base3:outLength * _p3;
    /* This transforms tensions of Infinity to 10000. Then we can interpolate
     * without creating NaN values.
     *
     * NaN is produced when a tension is Infinity and a proportion is zero:
     * Infinity * 0 => NaN.
     * AFAIK this behavior is mathematically correct.
     * But in that case we clearly want a 0 as result, because a proportion
     * of 0 means we don't want to include the master into the Interpolation.
     *
     * 10000 will set the control point very very close to the on-curve
     * point.
     * FIXME: it would be better to keep the Infinity value when all
     * `base*:**Tension` values are Infinity. But I think there is no way
     * to do this right now.
     * something like:
     * ifelse (isInfinity base1:inTension and _p1 equals 0) 0 (base1:inTension * _p1)
     * but that would require the new operators `ifelse` `isInfinity` `equals` `and`
     * and that would require the booleans `true` and `false` also, consequently
     * we'd like also to introduce `not` `or` `isNaN`
     * But we are holding off conditional execution at the moment, because
     * we don't want to introduce to much power/complexity in CPS.
     *
     * (base1:inTension * _p1) elseif (isInfinity base1:inTension and _p1 equals 0) 0
     *
     * In another situation we may wan't to `grow` a control point in
     * an interpolation. For better control, the master `not` having that
     * control point can set the tension value to some big value itself.
     * This is really the workaround for the missing `ifelse` etc.
     * What a good value is must be determined in the case itself. I think
     * it's likely that it would be well under 50 then.
     * FIXME: Thus it may better here to go with a lower replacement value
     * for Infinity, e.g. 10 or 100?
     */
    inTension: 0
        + (min 1000 base0:inTension * _p0)
        + (min 1000 base1:inTension * _p1)
        + (min 1000 base2:inTension * _p2)
        + (min 1000 base3:inTension * _p3);
    outTension: 0
        + (min 1000 base0:outTension * _p0)
        + (min 1000 base1:outTension * _p1)
        + (min 1000 base2:outTension * _p2)
        + (min 1000 base3:outTension * _p3);
    inDirIntrinsic: ((Vector 0 0)
        + (Polar 1 base0:inDirIntrinsic) * _p0
        + (Polar 1 base1:inDirIntrinsic) * _p1
        + (Polar 1 base2:inDirIntrinsic) * _p2
        + (Polar 1 base3:inDirIntrinsic) * _p3
        ):angle;
    outDirIntrinsic: ((Vector 0 0)
        + (Polar 1 base0:outDirIntrinsic) * _p0
        + (Polar 1 base1:outDirIntrinsic) * _p1
        + (Polar 1 base2:outDirIntrinsic) * _p2
        + (Polar 1 base3:outDirIntrinsic) * _p3
        ):angle;
}

contour > p {
    on: Vector 0 0
        + base0:on * _p0
        + base1:on * _p1
        + base2:on * _p2
        + base3:on * _p3;
    inDir: ((Vector 0 0)
        + (Polar 1  base0:inDir) * _p0
        + (Polar 1  base1:inDir) * _p1
        + (Polar 1  base2:inDir) * _p2
        + (Polar 1  base3:inDir) * _p3
        ):angle;
    outDir: ((Vector 0 0)
        + (Polar 1  base0:outDir) * _p0
        + (Polar 1  base1:outDir) * _p1
        + (Polar 1  base2:outDir) * _p2
        + (Polar 1  base3:outDir) * _p3
        ):angle;
    inTension: 0
        + (min 10000 base0:inTension) * _p0
        + (min 10000 base1:inTension) * _p1
        + (min 10000 base2:inTension) * _p2
        + (min 10000 base3:inTension) * _p3;
    outTension: 0
        + (min 10000 base0:outTension) * _p0
        + (min 10000 base1:outTension) * _p1
        + (min 10000 base2:outTension) * _p2
        + (min 10000 base3:outTension) * _p3;
}

center > left, center > right {
    onDir: ((Vector 0 0)
        + (Polar 1 base0:onDir) * _p0
        + (Polar 1 base1:onDir) * _p1
        + (Polar 1 base2:onDir) * _p2
        + (Polar 1 base3:onDir) * _p3
        ):angle;
    onLength: 0
        + base0:onLength * _p0
        + base1:onLength * _p1
        + base2:onLength * _p2
        + base3:onLength * _p3;
}

center {
    on: Vector 0 0
        + base0:on * _p0
        + base1:on * _p1
        + base2:on * _p2
        + base3:on * _p3;
    in: Vector 0 0
        + base0:in * _p0
        + base1:in * _p1
        + base2:in * _p2
        + base3:in * _p3;
    out: Vector 0 0
        + base0:out * _p0
        + base1:out * _p1
        + base2:out * _p2
        + base3:out * _p3;
}

/* terminals overide of skeleton2outline */
